        private void OnModalDialogueAccepted(long messageid, bool leftchoice)
        {
        if (messageid == 9999)
        {
            return;
        }
        if (messageid == CHOICE_GOAL)
        {
            if (!leftchoice)
            {
                SendMissionEvent(0);
                PlayNarration(REDPILL_DIALOG);
                CompleteGoal(CHOICE_GOAL);
            }
            else
            {
                PlayNarration(BLUEPILL_CONFIRM);
                SendModalMessage(CHOICE_CONFIRM, 0x8800002cu, 0, 0xc2000005u, 0xc2000001u);
            }
            return;
        }
        if (messageid == CHOICE_CONFIRM)
        {
            if (!leftchoice)
            {
                SendMissionEvent(0);
                PlayNarration(REDPILL_DIALOG);
                CompleteGoal(CHOICE_GOAL);
            }
            else
            {
                SendMissionEvent(0);
                PlayNarration(BLUEPILL_TAKEN);
                ScheduleEvent(5, BLUEPILL_TAKEN);
            }
            return;
        }
        if (messageid == RESPAWN_GOAL)
        {
            if (leftchoice)
            {
                RespawnNPC("Bob");
                UnkillNPC("Bob");
                PlayNarration(COMBAT_REMINDER);
            }
            else
            {
                CompleteGoal(RESPAWN_GOAL);
            }
            return;
        }
        return;
        }

        private void OnMissionEvent(long eventid)
